css:
@page {
    size: A4;
    margin: 5mm;
}

.line-spacing {
    line-height: 1.1; /* controls vertical spacing between lines */
    margin: 0;        /* optional: reset default margins */
}

/* ===== Header Styling ===== */
.header { position: relative;}

.logo {  position: absolute; left: 0; }

.demo1{
   position: relative; 
}
.demo{
    position: absolute;
    right: 0;
    bottom:0;
}

.borders { border: 1px solid #000; }
.borders-top { border-top: 1px solid #000; }
.borders-bottom { border-bottom: 1px solid #000; }
.borders-start { border-left: 1px solid #000; }
.borders-end { border-right: 1px solid #000; }

.mtt { margin-top: 15px; }

.same { height: 72px;}

/* ===== Row & Columns ===== */
.rows {
    display: flex;          /* Align columns side by side */
    flex-wrap: wrap;        /* Wrap to next line if needed */
}

.cols-1  { width: 8.3333%; }
.cols-2  { width: 16.6667%; }
.cols-3  { width: 25%; }
.cols-4  { width: 33.3333%; }
.cols-5  { width: 41.6667%; } /* Update */
.cols-6  { width: 50%; }
.cols-7  { width: 58.3333%; } /* Update */
.cols-8  { width: 66.6667%; }
.cols-9  { width: 75%; }
.cols-10 { width: 83.3333%; }
.cols-11 { width: 91.6667%; }
.cols-12 { width: 100%; }
.cols-13 { width: 15.3333%; }
.cols-77 { width: 51.3333%; }

/* ===== Font Weights & Sizes ===== */
.fweight-1 { font-weight: bold; }
.fweight-2 { font-weight: bolder; }

.fsize-0 { font-size: 8px; }
.fsize-01 { font-size: 9px; }
.fsize-1 { font-size: 10px; }
.fsize-2 { font-size: 15px; }
.fsize-3 { font-size: 20px; }

.block-gap {
    line-height: 1.5;
}
.d-flex-center {
    display: flex;
    justify-content: center; /* horizontal centering */
    align-items: center;     /* vertical centering */
}

.d-flex-end{
    display: flex;
    justify-content:space-between;
}

/* ===== Padding Utilities ===== */
.pa-0  { padding: 0; }
.pae-1 { padding-right: 2px; }
.pae-2 { padding-right: 4px; }
.pae-3 { padding-right: 8px; }
.pae-4 { padding-right: 12px; }
.pae-5 { padding-right: 100px; }

.pas-2 { padding-left: 15px; }

.pay-1 { padding-top: 4px; padding-bottom: 4px; }
.pay-2 { padding-top: 8px; padding-bottom: 8px; }

.pax-2 { padding-left: 8px; padding-right: 8px; }

/* ===== Text Alignment Utilities ===== */
.texts-start { text-align: left; }
.texts-end { text-align: right; }
.texts-bottom { vertical-align: text-bottom; }

/* ===== Table Styling ===== */
table {
    width: 100%;
    border-collapse: collapse;
}

th, td { border: 1px solid #000; }

.trr td { padding: 0px; }

th {
    text-align: center;
    background-color: #f8f8f8;
}

.total-row td { font-weight: bold; }

.subject{
    font-size: 8px;
    padding-left: 5px;
}
.transport{
    padding:0px;
    padding-right: 18px;
     
}
.declaration-row {
    display: flex;
    justify-content: space-between;
    width: 100%;
    line-height: 1.2;
    margin-top: 2px;
}
/* Declaration text grows naturally */
.decl-text {
    flex: 1;
}

/* Receiver signature is aligned to the LAST line of declaration */
.receiver-sign {
    white-space: nowrap;
    align-self: flex-end;     /* THIS aligns vertically to the last line */
    padding-left: 50px;
}

/* Align Authorized Signatory at same baseline */
.authorized-signatory {
    position: absolute;
    bottom: 5px;              /* Adjust only this number if needed */
    width: calc(100% - 10px);
    text-align: center;
}
